// «חיפוש לפי מילים מתוך הפרקים» כמו ב-Figma» — עבר QA 25.10.2026 (iPhone 17, TestFlight 1.0.0 (20) + OTA после commit 8e46758).
// מה רצוי: «המשתמש עובר למקטע «פרקי אבות» → בשדה החיפוש מוצג «חיפוש לפי מילים מתוך הפרקים»; במקטע «תהילים» נשאר הטקסט של תהילים»
// (Figma 641:2687, слой 641:2944; эталон New-Keren — решение владельца 19.10; AC в документации нет).
// Факт 25.10: «פרקי אבות» — «חיפוש לפי מילים מתוך הפרקים», «תהילים» — прежний «חיפוש לפי מספר פרק או מילים», 2 переключения (07cdd6-pirkei.png).
// Экран — под вкладкой «ברכות» (после #4cfbf19e). Поле пустое (иначе placeholder не виден).
// Кейс: .qa/tests/tehilim/TH-02-search-placeholder-rtl.md (обновлён 25.10). Выравнивание вправо и лупа — tl-04.
import { expect, driver } from '@wdio/globals';
import { goHome } from '../_lib/readiness-1910.ts';
import { searchField } from '../_lib/app-0710.ts';
import { saveShot, openTehilimScreen, segment, expectPlaceholder, searchPlaceholder, PH_TEHILIM, PH_AVOT } from '../_lib/app-2510.ts';

describe('25.10 — placeholder поиска «פרקי אבות» (#07cdd6)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('TH-02b «ברכות» → «פרקי אבות»: «חיפוש לפי מילים מתוך הפרקים»; «תהילים»: «חיפוש לפי מספר פרק או מילים»; туда-обратно ×2; после ввода и очистки — снова свой текст #07cdd6 #d6a68154 Figma 641:2687 @prod-safe', async () => {
    await openTehilimScreen();
    const f = (await searchField()) as unknown as WebdriverIO.Element;
    await f.clearValue();
    await segment('תהילים');
    await expectPlaceholder(PH_TEHILIM, 'תהילים (старт)');
    for (let i = 1; i <= 2; i++) {
      await segment('פרקי אבות');
      await expectPlaceholder(PH_AVOT, `פרקי אבות, переключение ${i}`);
      expect(await searchPlaceholder()).not.toContain('מספר פרק');
      if (i === 1) await saveShot('TH-02b-avot.png');
      await segment('תהילים');
      await expectPlaceholder(PH_TEHILIM, `תהילים, переключение ${i}`);
      expect(await searchPlaceholder()).not.toContain('מתוך הפרקים');
    }
    // Ввод и очистка в «פרקי אבות» — placeholder возвращается новый.
    await segment('פרקי אבות');
    const f2 = (await searchField()) as unknown as WebdriverIO.Element;
    await f2.setValue('משה');
    await f2.clearValue();
    if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
    await expectPlaceholder(PH_AVOT, 'פרקי אבות после ввода и очистки');
    await segment('תהילים');
  });
});
